// tests/unit/doubleTake.test.mjs
//
// Unit tests for Double Take 2.0 deterministic scheduling.
//
// The schedule is generated by generateDoubleTakeSchedule() in createGame.js
// and stored in RTDB as doubleTakeSchedule: [pos1, pos2].
// Activation is checked in the OK handler of renderGame.js:
//   questionNumber = opened-tile count + 1
//   isDoubleTake   = Array.isArray(sched) && sched.includes(questionNumber)

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { generateDoubleTakeSchedule } from '../../src/game/createGame.js';
import { DOUBLE_TAKE } from '../../src/config.js';

const { WINDOW_1, WINDOW_2 } = DOUBLE_TAKE.SCHEDULE;

// ---------------------------------------------------------------------------
// Scheduling tests — properties guaranteed by generateDoubleTakeSchedule()
// ---------------------------------------------------------------------------

test('schedule is a two-element array', () => {
    const sched = generateDoubleTakeSchedule();
    assert.ok(Array.isArray(sched), 'should be an array');
    assert.equal(sched.length, 2);
});

test('pos1 falls within WINDOW_1 (inclusive)', () => {
    for (let i = 0; i < 200; i++) {
        const [pos1] = generateDoubleTakeSchedule();
        assert.ok(pos1 >= WINDOW_1.min && pos1 <= WINDOW_1.max,
            `pos1=${pos1} outside [${WINDOW_1.min},${WINDOW_1.max}]`);
    }
});

test('pos2 falls within WINDOW_2 (inclusive)', () => {
    for (let i = 0; i < 200; i++) {
        const [, pos2] = generateDoubleTakeSchedule();
        assert.ok(pos2 >= WINDOW_2.min && pos2 <= WINDOW_2.max,
            `pos2=${pos2} outside [${WINDOW_2.min},${WINDOW_2.max}]`);
    }
});

test('pos1 is always strictly less than pos2 (windows do not overlap)', () => {
    assert.ok(WINDOW_1.max < WINDOW_2.min,
        'WINDOW_1.max must be < WINDOW_2.min so pos1 < pos2 is guaranteed');
    for (let i = 0; i < 200; i++) {
        const [pos1, pos2] = generateDoubleTakeSchedule();
        assert.ok(pos1 < pos2, `pos1=${pos1} not < pos2=${pos2}`);
    }
});

test('a 25-tile game produces exactly 2 Double Takes across all questions', () => {
    for (let trial = 0; trial < 100; trial++) {
        const sched = generateDoubleTakeSchedule();
        let dtCount = 0;
        for (let q = 1; q <= 25; q++) {
            if (sched.includes(q)) dtCount++;
        }
        assert.equal(dtCount, 2, `trial ${trial}: expected 2 DTs, got ${dtCount} for sched ${JSON.stringify(sched)}`);
    }
});

test('WINDOW_1 and WINDOW_2 do not overlap', () => {
    assert.ok(WINDOW_1.max < WINDOW_2.min,
        `WINDOW_1 [${WINDOW_1.min},${WINDOW_1.max}] must end before WINDOW_2 [${WINDOW_2.min},${WINDOW_2.max}] starts`);
});

test('both positions are valid 1-indexed question numbers (1–25)', () => {
    for (let i = 0; i < 200; i++) {
        const [pos1, pos2] = generateDoubleTakeSchedule();
        assert.ok(pos1 >= 1 && pos1 <= 25, `pos1=${pos1} out of range`);
        assert.ok(pos2 >= 1 && pos2 <= 25, `pos2=${pos2} out of range`);
    }
});

// ---------------------------------------------------------------------------
// Activation tests — the OK handler guard logic in renderGame.js
// ---------------------------------------------------------------------------

// Simulate the check: questionNumber = opened + 1; isDoubleTake = sched.includes(qNum)
function checkActivation(openedCount, sched) {
    const questionNumber = openedCount + 1;
    return Array.isArray(sched) && sched.includes(questionNumber);
}

test('activates when opened count + 1 matches pos1', () => {
    const sched = generateDoubleTakeSchedule();
    const [pos1] = sched;
    assert.equal(checkActivation(pos1 - 1, sched), true);
});

test('activates when opened count + 1 matches pos2', () => {
    const sched = generateDoubleTakeSchedule();
    const [, pos2] = sched;
    assert.equal(checkActivation(pos2 - 1, sched), true);
});

test('does not activate on non-scheduled question numbers', () => {
    // Use a fixed schedule and test adjacent positions
    const sched = [7, 15];
    for (const nonDT of [1, 6, 8, 14, 16, 25]) {
        assert.equal(checkActivation(nonDT - 1, sched), false,
            `question ${nonDT} should not activate`);
    }
});

test('does not activate when sched is null', () => {
    assert.equal(checkActivation(6, null), false);
});

test('does not activate when sched is not an array', () => {
    assert.equal(checkActivation(6, 'invalid'), false);
    assert.equal(checkActivation(6, undefined), false);
    assert.equal(checkActivation(6, {}), false);
});

// ---------------------------------------------------------------------------
// Opened-tile counting — mirrors the guard logic in renderGame.js
// ---------------------------------------------------------------------------

function buildCache(openedCount, answeredCount = 0, totalTiles = 25) {
    const cache = {};
    for (let i = 0; i < totalTiles; i++) {
        const id = `${Math.floor(i / 5)}-${i % 5}`;
        if (i < openedCount) {
            cache[id] = { opened: true, answered: i < answeredCount };
        } else {
            cache[id] = { opened: false, answered: false };
        }
    }
    return cache;
}

function questionNumberFromCache(cache) {
    return Object.values(cache).filter(t => t?.opened === true).length + 1;
}

test('question number is 1 at game start (no opened tiles)', () => {
    assert.equal(questionNumberFromCache(buildCache(0)), 1);
});

test('question number increments with each opened tile', () => {
    for (let n = 0; n <= 24; n++) {
        assert.equal(questionNumberFromCache(buildCache(n)), n + 1);
    }
});

test('answered tiles count toward opened (opened flag is set at question-post time)', () => {
    // A tile that is answered still has opened: true
    const cache = buildCache(10, 8); // 10 opened (8 of those also answered)
    assert.equal(questionNumberFromCache(cache), 11);
});

test('tiles without opened flag do not count', () => {
    // Tiles where opened is explicitly false or missing
    const cache = buildCache(0);
    Object.values(cache).forEach(t => { t.opened = false; });
    assert.equal(questionNumberFromCache(cache), 1);
});

// ---------------------------------------------------------------------------
// Play Again independence — each round gets a fresh schedule
// ---------------------------------------------------------------------------

test('two consecutive schedules are (almost certainly) not identical', () => {
    // Probabilistically: P(same) ≤ 1/(5*6) = 1/30 per trial — 100 trials is decisive
    let allSame = true;
    for (let i = 0; i < 100; i++) {
        const a = generateDoubleTakeSchedule();
        const b = generateDoubleTakeSchedule();
        if (a[0] !== b[0] || a[1] !== b[1]) { allSame = false; break; }
    }
    assert.equal(allSame, false, 'schedules should vary across rounds');
});
